  }
}
```
При наведении курсора кнопка меняет оттенок синего, а на дисплеях с плотностью ≥2x текст становится крупнее, улучшая читаемость на высококачественных экранах.

Для объединения двух массивов и одновременного удаления дубликатов удобно использовать объект Set, который хранит только уникальные значения. Пример:
```js
const arr1 = [1, 2, 3, 4];
const arr2 = [3, 4, 5, 6];

// Объединяем массивы с помощью spread‑оператора и сразу передаём их в Set
const mergedUnique = [...new Set([...arr1, ...arr2])];

console.log(mergedUnique); // [1, 2, 3, 4, 5, 6]
```
Если массивы содержат объекты, а уникальность определяется, например, по полю `id`, то понадобится более сложный подход:
```js
const a = [{id:1, name:'A'}, {id:2, name:'B'}];
const b = [{id:2, name:'B'}, {id:3, name:'C'}];

const map = new Map();
[a, b].flat().forEach(item => map.set(item.id, item));
const merged = [...map.values()];

console.log(merged);
// [{id:1, name:'A'}, {id:2, name:'B'}, {id:3, name:'C'}]
```
Таким способом вы получаете один массив без повторяющихся элементов. Если нужен порядок, сохраняемый из исходных массивов, можно использовать `filter` после объединения.

Для копирования объекта, содержащего вложенные структуры (другие объекты, массивы), нужен **глубокий клон**. Поверхностное копирование (`Object.assign` или spread‑оператор) копирует только ссылки на вложенные объекты, поэтому изменения в копии отразятся в оригинале.

Самый простой способ – использовать встроенную функцию `structuredClone`, доступную в современных браузерах и Node.js:
```js
const original = {
  name: 'Alice',
  address: { city: 'Moscow', zip: 101000 },
  hobbies: ['reading', 'sports']
};

const deepCopy = structuredClone(original);

deepCopy.address.city = 'Saint Petersburg';
deepCopy.hobbies.push('music');

console.log(original.address.city); // "Moscow" – не изменилось
console.log(original.hobbies);      // ["reading", "sports"] – не изменилось
```
Если `structuredClone` недоступен (например, в старых средах), можно воспользоваться одним из альтернативных методов:

1. **JSON‑сериализация** – подходит, когда объект содержит только данные, совместимые с JSON (нет функций, `Date`, `Map`, `Set`, `undefined` и т.п.).
```js
const deepCopy = JSON.parse(JSON.stringify(original));
```
2. **Рекурсивная функция** – реализует копирование любого типа, включая `Date`, `Map`, `Set`.
```js
function deepClone(value) {
  if (value === null || typeof value !== 'object') return value;
  if (value instanceof Date) return new Date(value);
  if (value instanceof Map) return new Map([...value]);
  if (value instanceof Set) return new Set([...value]);
  if (Array.isArray(value)) return value.map(deepClone);
  const cloned = {};
  for (const key in value) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      cloned[key] = deepClone(value[key]);
    }
  }
  return cloned;
}

const deepCopy = deepClone(original);
```
Выбирайте метод в зависимости от требований к совместимости и типам данных, которые могут встречаться в объекте.

Для элементов, которые появляются в DOM после загрузки страницы, удобно использовать **делегирование событий**: вешаем один обработчик на родительский элемент, а внутри проверяем, был ли клик по нужному дочернему элементу. Это избавляет от необходимости каждый раз привязывать обработчик к новому элементу.

```html
<ul id="list">
  <!-- элементы li будут добавляться динамически -->
</ul>
<button id="add">Добавить элемент</button>
```
```js
const list = document.getElementById('list');
const addBtn = document.getElementById('add');

// Делегируем событие click от списка
list.addEventListener('click', function (e) {
  // Проверяем, что клик был по элементу li
  if (e.target && e.target.matches('li.item')) {
    try {
      // Код обработчика, который может бросить ошибку
      console.log('Клик по элементу:', e.target.textContent);
      // Пример потенциальной ошибки
      if (e.target.textContent.includes('error')) {
        throw new Error('Симулированная ошибка');
      }
    } catch (err) {
      // Обработка ошибки – выводим в консоль и показываем пользователю
      console.error('Ошибка в обработчике клика:', err);
      alert('Произошла ошибка: ' + err.message);
    }
  }
});

// Добавляем новые элементы динамически
addBtn.addEventListener('click', () => {
  const li = document.createElement('li');
  li.className = 'item';
  li.textContent = Math.random() > 0.5 ? 'Элемент' : 'Элемент с error';
  list.appendChild(li);
});
```
**Что происходит:**
1. `list.addEventListener('click', …)` фиксирует любой клик внутри `<ul id="list">`.
2. `e.target.matches('li.item')` проверяет, что клик пришёл именно от элемента `li` с классом `item`.
3. Внутри `try…catch` помещён код, который может бросить исключение. При возникновении ошибки она перехватывается, выводится в консоль и показывается пользователю через `alert` (в реальном проекте лучше использовать более дружелюбный UI‑компонент).
4. Кнопка «Добавить элемент» создаёт новые `li`‑элементы; благодаря делегированию им автоматически будет назначен тот же обработчик без дополнительного кода.

Таким образом, вы получаете надёжный механизм обработки кликов по динамическим элементам и защищённый от необработанных исключений код обработчика.

Можно задать сетку из трёх колонок для широких экранов и переопределить её в медиазапросе для узких устройств. Пример:
