  grid-template-columns: repeat(3, 1fr); /* три равные колонки */
  gap: 16px;                           /* расстояние между элементами */
}

/* Медиазапрос для экранов ≤ 600 px */
@media (max-width: 600px) {
  .grid {
    grid-template-columns: 1fr;      /* одна колонка */
  }
}
```
